def tool_prompt_text(tool_id: str) -> str | None:
    """The portable prompt for one tool, or None for an unknown tool_id."""
    entry = TOOL_PROMPT_FILES.get(tool_id)
    return entry[1] if entry else None


def tollgate_prompt_text(phase: str) -> str | None:
    """The portable Champion prompt for one tollgate phase, or None."""
    entry = TOLLGATE_PROMPT_FILES.get(phase)
    return entry[1] if entry else None
